+/// Pinhole perspective camera looking at `target` with +Z world up.
+#[derive(Clone, Copy, Debug)]
+pub(super) struct Camera {
+    pub pos: Vec3,
+    pub fwd: Vec3,
+    pub right: Vec3,
+    pub up: Vec3,
