+fn rpc_call(srv: &mut Server, id: i64, name: &str, args: Value) -> Value {
+    let reply = srv
+        .handle(&json!({
+            "jsonrpc": "2.0",
+            "id": id,
+            "method": "tools/call",
+            "params": { "name": name, "arguments": args }
